    private TextView label(String text,int size){TextView v=new TextView(this);v.setText(text);v.setTextColor(-1);v.setTextSize(size);v.setTypeface(WorkspaceUi.font(this));return v;}
    private Button button(LinearLayout parent,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTypeface(WorkspaceUi.font(this));parent.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{if(!busy)action.run();});return b;}
    private void enabled(boolean on){busy=!on;for(View v:new View[]{more,close})if(v!=null)v.setEnabled(on);if(selector!=null)selector.setEnabled(on&&stagedHoleDeletion==null);if(input!=null)input.setEnabled(on&&!orphan&&stagedHoleDeletion==null);if(save!=null)save.setEnabled(on&&!orphan&&(stagedHoleDeletion==null||geometryConfirmationMatches(stagedHoleDeletion)));if(mode!=null)mode.setEnabled(on&&!orphan&&stagedHoleDeletion==null);if(mapCanvas!=null)mapCanvas.setEditingEnabled(on&&!orphan&&stagedHoleDeletion==null);}
    private void actions(){
        final List<String> choices=new ArrayList<>();GeometryEdits.Part part=parts.get(current);final String sourceText=input.getText().toString(),sourceToken=expected;
        if(stagedHoleDeletion!=null)choices.add("Отменить удаление контура");
        else{if(!orphan&&!addingHole&&part.polygon&&!part.hole)choices.add("Добавить внутренний контур");
        if(!orphan&&!addingHole&&part.hole)choices.add("Удалить внутренний контур");
        if(!orphan)choices.add("Редактировать вершины");}
        choices.add("Копировать ввод");choices.add("Перечитать объект");
        new AlertDialog.Builder(this).setTitle("Действия с контуром").setItems(choices.toArray(new String[choices.size()]),(d,w)->{String selected=choices.get(w);if(selected.equals("Отменить удаление контура")){cancelStagedHoleDeletion();}else if(selected.equals("Редактировать вершины")){textMode();vertices();}else if(selected.equals("Добавить внутренний контур"))newHole();else if(selected.equals("Удалить внутренний контур")){if(dirty()){status.setText("Сначала сохраните или отмените текущий ввод");return;}try{openGeometryConfirmation(new GeometryConfirmationDraft(project,featureId,VERTEX_SESSION,part.key,sourceToken,VertexEditDraft.stamp(sourceText),part.type,"hole",false,-1),"");}catch(IllegalArgumentException error){status.setText(error.getMessage());}}else if(selected.equals("Перечитать объект"))discardReload();else{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(clipboard!=null)clipboard.setPrimaryClip(ClipData.newPlainText("Координаты WGS 84",input.getText().toString()));}}).setNegativeButton("Закрыть",null).show();
    }
    private void vertices(){
        final GeometryEdits.Part sourcePart=parts.get(current);final String sourceToken=expected;final boolean sourceAdding=addingHole;
        final String text=input.getText().toString(),type=addingHole?"Polygon":parts.get(current).type;
        final List<String> rows;
        try{rows=GeometryVertices.rows(text,type);}catch(IllegalArgumentException e){input.setError(e.getMessage());return;}
        String[] names=new String[rows.size()];for(int i=0;i<names.length;i++)names[i]=(i+1)+". "+rows.get(i);
        new AlertDialog.Builder(this).setTitle("Вершины: широта долгота высота").setItems(names,(d,index)->{
            List<String> titles=new ArrayList<>(),operations=new ArrayList<>();
            titles.add("Изменить координаты");operations.add("replace");
            if(!"Point".equals(type)){
                titles.add("Вставить перед");operations.add("before");titles.add("Вставить после");operations.add("after");
                if(index>0){titles.add("Выше в списке");operations.add("up");}
                if(index+1<rows.size()){titles.add("Ниже в списке");operations.add("down");}
                titles.add("Удалить вершину");operations.add("delete");
            }
            new AlertDialog.Builder(this).setTitle("Вершина "+(index+1)).setItems(titles.toArray(new String[titles.size()]),(dialog,which)->{
                final String operation=operations.get(which);
                if(operation.equals("replace")||operation.equals("before")||operation.equals("after")){
                    try{openVertexEditor(new VertexEditDraft(project,featureId,VERTEX_SESSION,parts.get(current).key,expected,VertexEditDraft.stamp(text),type,addingHole,index,operation,rows.get(index),0,rows.get(index).length(),""));}catch(IllegalArgumentException error){status.setText(error.getMessage());}
                }else if(operation.equals("delete")){try{openGeometryConfirmation(new GeometryConfirmationDraft(project,featureId,VERTEX_SESSION,sourcePart.key,sourceToken,VertexEditDraft.stamp(text),type,"vertex",sourceAdding,index),"");}catch(IllegalArgumentException error){status.setText(error.getMessage());}}
                else applyVertex(text,type,index,operation,null,null);
            }).setNegativeButton("Отмена",null).show();
        }).setNegativeButton("Закрыть",null).show();
    }
    private boolean applyVertex(String original,String type,int index,String operation,String point,EditText field){return applyVertex(original,type,index,operation,point,field,null);}
    private boolean applyVertex(String original,String type,int index,String operation,String point,EditText field,TextView validation){
        if(busy||disposed||!input.getText().toString().equals(original)){status.setText("Ввод изменился; выберите вершину заново");return false;}
        try{String updated=GeometryVertices.edit(original,type,index,operation,point);clearNotice();input.setText(updated);input.setError(null);status.setText("Вершины изменены во вводе. Для записи объекта нажмите «Сохранить»");return true;}
        catch(IllegalArgumentException e){if(validation!=null){validation.setText(e.getMessage());validation.setVisibility(View.VISIBLE);}else if(field!=null)field.setError(e.getMessage());else status.setText(e.getMessage());return false;}
    }
    private GeometryPartChoiceDraft readPartChoice(Bundle b){if(b==null)return null;try{return new GeometryPartChoiceDraft(b.getLong("project"),b.getString("feature"),b.getString("session"),b.getString("sourceKey"),b.getString("sourceToken"),b.getString("sourceType"),b.getBoolean("adding"),b.getBoolean("map"),b.getString("stamp"),b.getString("targetKey"),b.getString("targetToken"),b.getString("targetType"));}catch(RuntimeException invalid){return null;}}
    private Bundle savePartChoice(){GeometryPartChoiceDraft d=partChoice!=null?partChoice:pendingPartChoice;if(d==null)return null;Bundle b=new Bundle();b.putLong("project",d.project);b.putString("feature",d.feature);b.putString("session",d.session);b.putString("sourceKey",d.sourceKey);b.putString("sourceToken",d.sourceToken);b.putString("sourceType",d.sourceType);b.putBoolean("adding",d.addingHole);b.putBoolean("map",d.onMap);b.putString("stamp",d.mainStamp);b.putString("targetKey",d.targetKey);b.putString("targetToken",d.targetToken);b.putString("targetType",d.targetType);b.putString("error",boundedConfirmationError(d==pendingPartChoice?pendingPartChoiceError:partChoiceError));return b;}
    private int choiceTarget(GeometryPartChoiceDraft d){if(parts!=null)for(int i=0;i<parts.size();i++)if(parts.get(i).key.equals(d.targetKey))return i;return -1;}
    private boolean partChoiceMatches(GeometryPartChoiceDraft d){if(d==null||orphan||input==null||parts==null||current<0||current>=parts.size())return false;int target=choiceTarget(d);if(target<0)return false;GeometryEdits.Part source=parts.get(current),to=parts.get(target);return d.matches(project,featureId,VERTEX_SESSION,source.key,expected,source.token,source.type,source.hole,addingHole,mapMode,input.getText().toString(),to.key,to.token,to.type,to.hole);}
    private void requestPartChoice(int target){if(busy||disposed||target<0||target>=parts.size()||target==current)return;GeometryEdits.Part source=parts.get(current),to=parts.get(target);try{openPartChoice(new GeometryPartChoiceDraft(project,featureId,VERTEX_SESSION,source.key,expected,source.type,addingHole,mapMode,VertexEditDraft.stamp(input.getText().toString()),to.key,to.token,to.type),"");}catch(IllegalArgumentException invalid){status.setText(invalid.getMessage());}}
    private void restorePartChoice(){GeometryPartChoiceDraft d=pendingPartChoice;pendingPartChoice=null;String error=pendingPartChoiceError;pendingPartChoiceError="";if(d==null)return;if(!d.inSession(project,featureId,VERTEX_SESSION)){status.setText("Смена контура другого объекта или процесса не восстановлена");return;}if(vertexDialog!=null||geometryConfirmationDialog!=null){status.setText("Одновременные диалоги не восстановлены");return;}openPartChoice(d,error);}
    private void clearPartChoice(AlertDialog dialog){if(partChoiceDialog!=dialog)return;partChoiceDialog=null;partChoice=null;partChoiceError="";boolean checking=partChoiceChecking;partChoiceChecking=false;if(checking&&!disposed)enabled(true);}
    private void partChoiceFailure(GeometryPartChoiceDraft d,AlertDialog dialog,String error,boolean terminal){if(partChoice!=d||partChoiceDialog!=dialog)return;partChoiceError=boundedConfirmationError(error);dialog.setMessage("Сменить контур и отменить несохранённый ввод?\n\n"+partChoiceError);vertexFont(dialog.getWindow().getDecorView());dialog.getButton(-1).setEnabled(!terminal&&partChoiceMatches(d)&&!busy);}
    private void openPartChoice(final GeometryPartChoiceDraft d,String error){if(disposed||partChoiceDialog!=null)return;partChoice=d;partChoiceError=boundedConfirmationError(error);if(!partChoiceMatches(d)&&partChoiceError.isEmpty())partChoiceError="Геометрия или исходный ввод изменились. Смена контура заблокирована.";final AlertDialog dialog=new AlertDialog.Builder(this).setMessage("Сменить контур и отменить несохранённый ввод?"+(partChoiceError.isEmpty()?"":"\n\n"+partChoiceError)).setPositiveButton("Сменить контур",null).setNegativeButton("Продолжить редактирование",(closed,which)->clearPartChoice((AlertDialog)closed)).create();partChoiceDialog=dialog;dialog.setOnDismissListener(closed->clearPartChoice(dialog));dialog.setOnShowListener(shown->{vertexFont(dialog.getWindow().getDecorView());if(getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE)dialog.getWindow().setLayout(-1,-2);dialog.getButton(-1).setEnabled(partChoiceMatches(d)&&!busy);dialog.getButton(-1).setOnClickListener(v->confirmPartChoice(d,dialog));});dialog.show();}
    private void confirmPartChoice(final GeometryPartChoiceDraft d,final AlertDialog dialog){
        if(disposed||busy||partChoiceChecking||partChoice!=d||partChoiceDialog!=dialog)return;
        if(!partChoiceMatches(d)){partChoiceFailure(d,dialog,"Геометрия или исходный ввод изменились. Смена контура заблокирована.",true);return;}
        if(!persist()){partChoiceFailure(d,dialog,status.getText().toString(),false);return;}final GeometryDraft discarded=ownedDraft;partChoiceChecking=true;enabled(false);dialog.getButton(-1).setEnabled(false);
        worker.execute(()->{ProjectStore store=null;String failure=null;try{store=new ProjectStore(this);Element feature=store.load(d.project).byId(d.feature);boolean source=false,target=false;if(feature!=null)for(GeometryEdits.Part part:GeometryEdits.parts(feature)){if(d.sourceKey.equals(part.key)&&d.sourceToken.equals(part.token)&&d.sourceType.equals(part.type)&&d.sourceHole==part.hole)source=true;if(d.targetKey.equals(part.key)&&d.targetToken.equals(part.token)&&d.targetType.equals(part.type)&&d.targetHole==part.hole)target=true;}if(!source||!target)failure="Исходный или выбранный контур изменился. Смена контура заблокирована.";}catch(Exception invalid){failure="Не удалось проверить контуры: "+invalid.getMessage();}finally{if(store!=null)store.close();}final String error=failure;
            runOnUiThread(()->{if(disposed||partChoice!=d||partChoiceDialog!=dialog)return;partChoiceChecking=false;enabled(true);if(error!=null||!partChoiceMatches(d)){partChoiceFailure(d,dialog,error!=null?error:"Исходный ввод изменился. Смена контура заблокирована.",true);return;}try{if(discarded!=null&&!GeometryDraft.discardIfMatches(drafts(),project,featureId,discarded)){partChoiceFailure(d,dialog,"Более новый черновик оставлен. Перечитайте объект.",true);return;}int target=choiceTarget(d);clearPartChoice(dialog);dialog.dismiss();ownedDraft=null;choosePart(target);selecting=true;selector.setSelection(target);selecting=false;enabled(true);}catch(IOException invalid){partChoiceFailure(d,dialog,invalid.getMessage(),false);}});
        });
    }

    private String boundedConfirmationError(String value){return value==null?"":value.substring(0,Math.min(2048,value.length()));}
    private GeometryConfirmationDraft readGeometryConfirmation(Bundle b){if(b==null)return null;try{return new GeometryConfirmationDraft(b.getLong("project"),b.getString("feature"),b.getString("session"),b.getString("key"),b.getString("token"),b.getString("mainStamp"),b.getString("type"),b.getString("kind"),b.getBoolean("adding"),b.getInt("index"),b.getBoolean("map",false));}catch(RuntimeException e){return null;}}
    private Bundle saveGeometryConfirmation(){GeometryConfirmationDraft d=geometryConfirmation!=null?geometryConfirmation:stagedHoleDeletion!=null?stagedHoleDeletion:pendingGeometryConfirmation;if(d==null)return null;Bundle b=new Bundle();b.putLong("project",d.project);b.putString("feature",d.feature);b.putString("session",d.session);b.putString("key",d.key);b.putString("token",d.token);b.putString("mainStamp",d.mainStamp);b.putString("type",d.type);b.putString("kind",d.kind);b.putBoolean("adding",d.addingHole);b.putBoolean("map",d.onMap);b.putInt("index",d.index);b.putBoolean("staged",d==stagedHoleDeletion||d==pendingGeometryConfirmation&&restoreHoleDeletion);b.putString("error",boundedConfirmationError(d==pendingGeometryConfirmation?pendingGeometryError:geometryConfirmationError));return b;}
    private boolean geometryConfirmationMatches(GeometryConfirmationDraft d){if(d==null||input==null||parts==null||current<0||current>=parts.size()||orphan)return false;GeometryEdits.Part part=parts.get(current);return (!d.onMap||mapMode&&mapCanvas!=null&&mapState!=null&&mapState.selected()==d.index&&mapState.text().equals(input.getText().toString()))&&expected.equals(d.token)&&d.matches(project,featureId,VERTEX_SESSION,part.key,part.token,part.type,part.hole,addingHole,input.getText().toString());}
    private String geometryConfirmationMessage(GeometryConfirmationDraft d){return d.onMap?"Удалить выбранную вершину из текущего ввода?\n\nВершина "+(d.index+1):d.kind.equals("hole")?"Удалить только выбранный внутренний контур? Остальная область сохраняется.\n\nУдаление будет записано только кнопкой «Сохранить».":"Удалить вершину "+(d.index+1)+" из текущего ввода?";}
    private void cancelStagedHoleDeletion(){stagedHoleDeletion=null;enabled(true);status.setText("Удаление контура отменено; проект не изменён");}
    private void restoreGeometryConfirmation(){GeometryConfirmationDraft d=pendingGeometryConfirmation;pendingGeometryConfirmation=null;boolean staged=restoreHoleDeletion;restoreHoleDeletion=false;String error=pendingGeometryError;pendingGeometryError="";if(d==null)return;if(!d.inSession(project,featureId,VERTEX_SESSION)){status.setText("Подтверждение другого объекта или процесса не восстановлено");return;}if(vertexDialog!=null){status.setText("Одновременные диалоги не восстановлены");return;}if(staged){if(!d.kind.equals("hole")){status.setText("Недопустимое намерение удаления отклонено");return;}stagedHoleDeletion=d;enabled(true);status.setText(geometryConfirmationMatches(d)?"Удаление контура подготовлено. Для записи нажмите «Сохранить»":"Удаление заблокировано: геометрия или ввод изменились. Отмените намерение через «Действия»");}else openGeometryConfirmation(d,error);}
    private void clearGeometryConfirmation(AlertDialog dialog){if(geometryConfirmationDialog!=dialog)return;boolean checking=geometryChecking;geometryChecking=false;geometryConfirmation=null;geometryConfirmationDialog=null;geometryConfirmationError="";if(checking&&!disposed)enabled(true);}
    private void geometryConfirmationError(GeometryConfirmationDraft d,AlertDialog dialog,String error,boolean blocked){if(geometryConfirmation!=d||geometryConfirmationDialog!=dialog)return;geometryConfirmationError=boundedConfirmationError(error);dialog.setMessage(geometryConfirmationMessage(d)+(geometryConfirmationError.isEmpty()?"":"\n\n"+geometryConfirmationError));dialog.getButton(-1).setEnabled(!blocked&&geometryConfirmationMatches(d)&&!busy);vertexFont(dialog.getWindow().getDecorView());}
    private void openGeometryConfirmation(final GeometryConfirmationDraft d,String error){
        if(disposed||geometryConfirmationDialog!=null||vertexDialog!=null||stagedHoleDeletion!=null)return;if(!d.inSession(project,featureId,VERTEX_SESSION)){status.setText("Чужое намерение удаления отклонено");return;}
        geometryConfirmation=d;geometryConfirmationError=boundedConfirmationError(error);if(!geometryConfirmationMatches(d))geometryConfirmationError="Геометрия или исходный ввод изменились. Подтверждение заблокировано; отмените его и выберите действие заново.";
        final AlertDialog dialog=new AlertDialog.Builder(this).setMessage(geometryConfirmationMessage(d)+(geometryConfirmationError.isEmpty()?"":"\n\n"+geometryConfirmationError)).setPositiveButton(d.kind.equals("hole")?"Удалить контур":"Удалить",null).setNegativeButton("Отмена",(closed,which)->clearGeometryConfirmation((AlertDialog)closed)).create();geometryConfirmationDialog=dialog;
        dialog.setOnDismissListener(closed->clearGeometryConfirmation(dialog));dialog.setOnShowListener(shown->{vertexFont(dialog.getWindow().getDecorView());dialog.getButton(-1).setEnabled(geometryConfirmationMatches(d)&&!busy);dialog.getButton(-1).setOnClickListener(v->confirmGeometryDeletion(d,dialog));});dialog.show();
    }
    private void confirmGeometryDeletion(final GeometryConfirmationDraft d,final AlertDialog dialog){
        if(disposed||busy||geometryConfirmation!=d||geometryConfirmationDialog!=dialog)return;
        if(!geometryConfirmationMatches(d)){geometryConfirmationError(d,dialog,"Геометрия или исходный ввод изменились. Подтверждение заблокировано.",true);return;}
        if(!persist()){geometryConfirmationError(d,dialog,status.getText().toString(),false);return;}
        geometryChecking=true;enabled(false);dialog.getButton(-1).setEnabled(false);
        worker.execute(()->{ProjectStore store=null;String failure=null;try{store=new ProjectStore(this);Element feature=store.load(d.project).byId(d.feature);boolean valid=false;if(feature!=null)for(GeometryEdits.Part part:GeometryEdits.parts(feature))if(d.key.equals(part.key)&&d.token.equals(part.token)&&d.type.equals(part.type)&&d.hole==part.hole){valid=true;break;}if(!valid)failure="Геометрия изменилась или объект удалён. Подтверждение заблокировано.";}catch(Exception error){failure="Не удалось проверить исходный объект: "+error.getMessage();}finally{if(store!=null)store.close();}final String error=failure;
            runOnUiThread(()->{if(disposed||geometryConfirmation!=d||geometryConfirmationDialog!=dialog)return;geometryChecking=false;enabled(true);if(error!=null||!geometryConfirmationMatches(d)){geometryConfirmationError(d,dialog,error!=null?error:"Исходный ввод изменился. Подтверждение заблокировано.",true);return;}
                if(d.kind.equals("vertex")){if(d.onMap){if(mapCanvas==null||!mapCanvas.deleteConfirmed(d.index)){geometryConfirmationError(d,dialog,"Выбранная вершина изменилась. Подтверждение заблокировано.",true);return;}clearGeometryConfirmation(dialog);dialog.dismiss();return;}if(!applyVertex(input.getText().toString(),d.type,d.index,"delete",null,null)){geometryConfirmationError(d,dialog,status.getText().toString(),false);return;}clearGeometryConfirmation(dialog);dialog.dismiss();}
                else{clearGeometryConfirmation(dialog);dialog.dismiss();stagedHoleDeletion=d;enabled(true);status.setText("Удаление контура подготовлено. Для записи нажмите «Сохранить». Для отмены — «Действия» или «Назад»");}
            });
        });
    }

    private VertexEditDraft readVertex(Bundle b){if(b==null)return null;try{return new VertexEditDraft(b.getLong("project"),b.getString("feature"),b.getString("session"),b.getString("key"),b.getString("token"),b.getString("mainStamp"),b.getString("type"),b.getBoolean("hole"),b.getInt("index"),b.getString("operation"),b.getString("raw"),b.getInt("start"),b.getInt("end"),b.getString("error"));}catch(IllegalArgumentException e){return null;}}
