    private void openClose(final GeometryCloseDraft d,String error){if(disposed||closeDialog!=null)return;closeDraft=d;closeError=boundedConfirmationError(error);if(!closeMatches(d)&&closeError.isEmpty())closeError="Исходный ввод изменился. Закрытие заблокировано; отмените подтверждение.";final AlertDialog dialog=new AlertDialog.Builder(this).setMessage("Сохранить ввод как локальный черновик и закрыть редактор?"+(closeError.isEmpty()?"":"\n\n"+closeError)).setPositiveButton("Сохранить черновик",null).setNegativeButton("Продолжить редактирование",(closed,which)->clearClose((AlertDialog)closed)).setNeutralButton("Отменить ввод",null).create();closeDialog=dialog;dialog.setOnDismissListener(closed->clearClose(dialog));dialog.setOnShowListener(shown->{vertexFont(dialog.getWindow().getDecorView());if(getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE){dialog.getWindow().setLayout(-1,-2);int inset=WorkspaceUi.dp(this,8);for(int which:new int[]{-1,-2,-3}){Button action=dialog.getButton(which);action.setPadding(inset,action.getPaddingTop(),inset,action.getPaddingBottom());}}boolean allowed=closeMatches(d)&&!busy&&!closeDraftConflict;dialog.getButton(-1).setEnabled(allowed);dialog.getButton(-3).setEnabled(allowed);dialog.getButton(-1).setOnClickListener(v->confirmClose(d,dialog,false));dialog.getButton(-3).setOnClickListener(v->confirmClose(d,dialog,true));});dialog.show();}
    private boolean samePrivateDraft(GeometryDraft a,GeometryDraft b){return a==null?b==null:b!=null&&a.key.equals(b.key)&&a.token.equals(b.token)&&a.text.equals(b.text)&&a.addingHole==b.addingHole;}
    private void confirmClose(GeometryCloseDraft d,AlertDialog dialog,boolean discard){if(disposed||busy||closeDraft!=d||closeDialog!=dialog)return;if(!closeMatches(d)){closeFailure(d,dialog,"Исходный ввод изменился. Закрытие заблокировано.");return;}try{synchronized(GeometryDraft.class){GeometryDraft now=GeometryDraft.load(drafts(),project,featureId);if(!samePrivateDraft(now,ownedDraft)){closeDraftConflict=true;closeFailure(d,dialog,"Более новый черновик оставлен. Перечитайте объект.");return;}if(discard){if(ownedDraft!=null&&!GeometryDraft.discardIfMatches(drafts(),project,featureId,ownedDraft)){closeDraftConflict=true;closeFailure(d,dialog,"Более новый черновик оставлен. Перечитайте объект.");return;}ownedDraft=null;}else if(!persist()){closeFailure(d,dialog,status.getText().toString());return;}closeDecisionComplete=true;clearClose(dialog);dialog.dismiss();finish();}}catch(IOException invalid){closeFailure(d,dialog,invalid.getMessage());}}
    // Keep the pre-existing missing-part close path until its separate baseline is measured.
    private void showOrphanClose(){new AlertDialog.Builder(this).setMessage("Сохранить ввод как локальный черновик и закрыть редактор?").setPositiveButton("Сохранить черновик",(d,w)->{if(persist())finish();}).setNegativeButton("Продолжить редактирование",null).setNeutralButton("Отменить ввод",(d,w)->{try{GeometryDraft.delete(drafts(),project,featureId);base=input.getText().toString();addingHole=false;finish();}catch(IOException e){status.setText(e.getMessage());}}).show();}
    public void onBackPressed(){if(busy){status.setText("Дождитесь окончания операции");return;}if(stagedHoleDeletion!=null){cancelStagedHoleDeletion();return;}if(closeDialog!=null)return;if(!dirty()){finish();return;}if(orphan){showOrphanClose();return;}if(current<0)return;if(mapCanvas!=null)mapCanvas.cancelGesture();try{GeometryEdits.Part part=parts.get(current);openClose(new GeometryCloseDraft(project,featureId,VERTEX_SESSION,part.key,expected,part.type,addingHole,mapMode,VertexEditDraft.stamp(input.getText().toString())),"");}catch(IllegalArgumentException invalid){status.setText(invalid.getMessage());}}
    public Object onRetainNonConfigurationInstance(){
        if(disposed||busy||!mapMode||mapState==null||current<0||input==null)return null;
        if(mapCanvas!=null)mapCanvas.cancelGesture();
        if(!mapState.canUndo()||!mapState.text().contentEquals(input.getText()))return null;
        try{return new GeometryMapUndoDraft(project,featureId,VERTEX_SESSION,parts.get(current).key,expected,mapState);}catch(IllegalArgumentException invalid){return null;}
    }
    protected void onSaveInstanceState(Bundle state){if(mapCanvas!=null)mapCanvas.cancelGesture();persist();state.putLong("geometry_owner",project);state.putString("geometry_feature",featureId);state.putBundle("geometry_confirmation",saveGeometryConfirmation());state.putBundle("part_choice",savePartChoice());state.putBundle("close_intent",saveClose());state.putBundle("vertex",saveVertex());state.putBoolean("geometry_map",mapMode);state.putString("geometry_part",current>=0?parts.get(current).key:preferredKey);state.putInt("geometry_selected",mapState==null?-1:mapState.selected());state.putDoubleArray("geometry_viewport",mapCanvas==null?mapViewport:mapCanvas.viewport());super.onSaveInstanceState(state);}
    protected void onPause(){if(mapCanvas!=null)mapCanvas.suspend(true);persist();super.onPause();}
    protected void onResume(){super.onResume();if(mapCanvas!=null)mapCanvas.suspend(false);}
    protected void onDestroy(){disposed=true;if(closeDialog!=null)closeDialog.dismiss();if(partChoiceDialog!=null)partChoiceDialog.dismiss();if(geometryConfirmationDialog!=null)geometryConfirmationDialog.dismiss();if(vertexDialog!=null)vertexDialog.dismiss();releaseMap();if(notice!=null)notice.cancel();worker.shutdown();super.onDestroy();}
